<?php declare(strict_types=1);namespace App\Controllers;use App\Core\{Controller,Security};use App\Models\ToolRun;use App\Services\AiService;final class ToolController extends Controller{private array $tools=['seo-analyzer','grammar-checker','readability-checker','content-optimizer','ai-detector','ai-humanizer','originality-checker','eeat-checker','bing-seo-checker','google-helpful-content-checker','keyword-density-checker','keyword-placement-checker','internal-link-suggestions','external-link-suggestions','entity-analyzer','heading-analyzer','title-generator','meta-generator','slug-generator','schema-generator','faq-generator','content-gap-analyzer','topic-coverage-analyzer','image-seo-checker','content-risk-analyzer','ai-visibility-analyzer','publish-readiness-checker','overall-content-quality-checker','image-compressor','image-extension-changer'];public function index():void{$this->view('plugins.tools',['title'=>'Tools','tools'=>$this->tools]);}public function run():void{Security::verify();$tool=$this->input('tool');$content=$this->input('content');if(!in_array($tool,$this->tools,true)||mb_strlen($content)<20){$this->json(['error'=>'Choose a valid tool and enter at least 20 characters.'],422);return;}$uid=$_SESSION['user_id']??null;$role=$_SESSION['role']??'guest';$runs=new ToolRun($this->db);$limit=$role==='premium_user'?PHP_INT_MAX:($uid?5:2);if($runs->usage($uid? (int)$uid:null,$_SERVER['REMOTE_ADDR']??'0.0.0.0')>=$limit){$this->json(['error'=>'Free usage limit reached. Please upgrade.'],402);return;}$result=(new AiService($this->config))->analyze($tool,$content);$runs->create(['user_id'=>$uid,'ip'=>$_SERVER['REMOTE_ADDR']??'0.0.0.0','tool'=>$tool,'input'=>$content,'output'=>json_encode($result),'score'=>$result['score']]);$this->json(['data'=>$result]);}}
